script:
(function () {
  'use strict';
  // Minister's housing exclusion, IRC section 107, following IRS Publication 517 (2025 edition, the
  // latest; downloaded from irs.gov and compared in this session):
  //   Allowance: excludable = smallest of designated allowance, amount actually spent to provide the home,
  //              and fair rental value of the home including furnishings plus utilities (Worksheet 1, 4a-4i).
  //   Parsonage: fair rental value excluded; utility allowance excluded up to actual utility costs (3a-3e).
  //   SE tax:    the exclusion is for income tax only. Active ministers without an approved Form 4361
  //              exemption include the allowance / parsonage value (plus utility allowance) in SE earnings;
  //              retired ministers' housing is not included.
  // Checked under Node (scratchpad/tests/b7basic/ch_test.js) against Pub. 517 examples: Rev. Baker
  // (parsonage FRV $24,000, utility allowance $7,500, actual utilities $7,000) excludes $31,000 with $500
  // taxable; Pastor Adams' SE housing amount is $17,000 ($12,000 FRV + $5,000 utility allowance). Each of
  // the three allowance limits was tested as the binding one. SE estimate: 24,000 x 0.9235 x 0.153 = 3,391.09.
  // ---- Tax constants (tax year 2026) ----
  // Self-employment tax: 92.35% of net earnings (Schedule SE) taxed at 15.3% (12.4% Social Security +
  // 2.9% Medicare), IRC sections 1401-1402, as described in IRS Pub. 517 (2025). The rates are statutory
  // and unchanged for 2026. SS wage base 2026: $184,500 (SSA 2026 COLA fact sheet), shown in the note only.
  var TAX_YEAR = 2026;
  var SE_NET_FACTOR = 0.9235;
  var SE_RATE = 0.153;
  var SS_WAGE_BASE = 184500;

  // Housing allowance (minister provides own home): IRS Pub. 517 Worksheet 1, lines 4a-4i.
  // Excludable = smallest of the designated allowance, actual expenses, and fair rental value
  // (furnished) plus utilities. Excess allowance is taxable income.
  function allowanceCase(designated, expenses, frvHome, frvFurnish, utilities) {
    var frvTotal = frvHome + frvFurnish + utilities;
    var excludable = Math.min(designated, expenses, frvTotal);
    var limit = excludable === designated ? 'designated' : (excludable === expenses ? 'expenses' : 'frv');
    return { excludable: excludable, excess: designated - excludable, frvTotal: frvTotal, limit: limit,
             seHousing: designated };
  }

  // Parsonage provided by the church: Pub. 517 Worksheet 1, lines 3a-3e. The fair rental value is
  // excluded; a utility allowance is excluded only up to actual utility costs.
  function parsonageCase(frv, utilAllowance, utilActual) {
    var utilExcluded = Math.min(utilAllowance, utilActual);
    return { excludable: frv + utilExcluded, excess: utilAllowance - utilExcluded, utilExcluded: utilExcluded,
             seHousing: frv + utilAllowance };
  }

  // Housing amount counted for SE tax: none if retired (Pub. 517: rental value or allowance provided
  // after retirement is not included) or exempt via an approved Form 4361.
  function seOnHousing(seHousing, retired, exempt) {
    var base = retired || exempt ? 0 : seHousing;
    return { base: base, tax: base * SE_NET_FACTOR * SE_RATE };
  }

  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var EXPENSE_IDS = ['chExpMortgage', 'chExpTaxes', 'chExpInsurance', 'chExpUtilities', 'chExpFurnishings', 'chExpRepairs', 'chExpHoa', 'chExpOther'];
  var ALL_IDS = ['chDesignated', 'chFrvHome', 'chFrvFurnish', 'chParsonageFrv', 'chUtilAllowance', 'chUtilActual'].concat(EXPENSE_IDS);

  // Blank counts as 0; returns NaN for negative or unreadable values.
  function amount(id) {
    var input = document.getElementById(id);
    if (input.value.trim() === '') return input.validity && input.validity.badInput ? NaN : 0;
    var v = parseFloat(input.value);
    return isNaN(v) || v < 0 || v > 1e9 ? NaN : v;
  }
  function set(id, text) { document.getElementById(id).textContent = text; }

  function fillLimits(rows) {
    var body = document.getElementById('chLimits');
    while (body.firstChild) body.removeChild(body.firstChild);
    rows.forEach(function (r) {
      var tr = document.createElement('tr');
      var th = document.createElement('td');
      th.textContent = r[0];
      if (r[2]) {
        var badge = document.createElement('span');
        badge.className = 'badge badge-pistachio ml-2';
        badge.textContent = r[2];
        th.appendChild(badge);
      }
      var td = document.createElement('td');
      td.textContent = money.format(r[1]);
      tr.appendChild(th); tr.appendChild(td);
      body.appendChild(tr);
    });
  }

  function update() {
    var mode = document.getElementById('chMode').value;
    var retired = document.getElementById('chStatus').value === 'retired';
    var exempt = document.getElementById('chExempt').checked;
    document.getElementById('chAllowanceInputs').hidden = mode !== 'allowance';
    document.getElementById('chParsonageInputs').hidden = mode !== 'parsonage';

    var error = document.getElementById('chError');
    var bad = ALL_IDS.some(function (id) { return isNaN(amount(id)); });
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter amounts of $0 or more (leave a box blank for $0).';
      ['chExcludable', 'chExcess', 'chSeBase', 'chSeTax', 'chSummary', 'chSeNote'].forEach(function (id) { set(id, id === 'chSummary' || id === 'chSeNote' ? '' : '–'); });
      fillLimits([]);
      return;
    }

    var r, summary;
    if (mode === 'allowance') {
      var expenses = EXPENSE_IDS.reduce(function (s, id) { return s + amount(id); }, 0);
      r = allowanceCase(amount('chDesignated'), expenses, amount('chFrvHome'), amount('chFrvFurnish'), amount('chExpUtilities'));
      var low = 'Lowest';
      fillLimits([
        ['Designated allowance', amount('chDesignated'), r.limit === 'designated' ? low : ''],
        ['Actual housing expenses', expenses, r.limit === 'expenses' ? low : ''],
        ['Fair rental value, furnished, plus utilities', r.frvTotal, r.limit === 'frv' ? low : '']
      ]);
      var why = { designated: 'your designated allowance', expenses: 'what you actually spent on housing', frv: 'the fair rental value of your home, furnished, plus utilities' }[r.limit];
      summary = r.excess > 0
        ? 'You can exclude ' + money.format(r.excludable) + ', limited by ' + why + '. The other ' + money.format(r.excess) +
          ' of the allowance is taxable: report it on Form 1040 as “Excess allowance” (line 1h on the 2025 form).'
        : 'Your whole ' + money.format(r.excludable) + ' allowance is tax-free for income tax, because it is not more than your actual expenses or the fair rental value plus utilities.';
      if (amount('chDesignated') === 0) summary = 'Enter the housing allowance your church designated to see how much of it is tax-free.';
    } else {
      var util = amount('chUtilAllowance'), actual = amount('chUtilActual');
      r = parsonageCase(amount('chParsonageFrv'), util, actual);
      fillLimits([
        ['Fair rental value of the parsonage (excluded)', amount('chParsonageFrv'), ''],
        ['Utility allowance paid to you', util, ''],
        ['Utilities you actually paid', actual, ''],
        ['Utility allowance excluded (smaller of the two)', r.utilExcluded, 'Excluded']
      ]);
      summary = 'The parsonage’s ' + money.format(amount('chParsonageFrv')) + ' rental value is not taxable income, and ' + money.format(r.utilExcluded) +
        ' of your utility allowance is tax-free.' + (r.excess > 0 ? ' The unused ' + money.format(r.excess) + ' of the utility allowance is taxable income.' : '');
    }

    var se = seOnHousing(r.seHousing, retired, exempt);
    set('chExcludable', money.format(r.excludable));
    set('chExcess', money.format(r.excess));
    set('chSeBase', money.format(se.base));
    set('chSeTax', money.format(se.tax));
    set('chSummary', summary);
    var seNote;
    if (retired) seNote = 'Retired: housing provided as part of your pension or for past service is not counted for self-employment tax.';
    else if (exempt) seNote = 'With an approved Form 4361 exemption, your ministerial earnings, including housing, are not subject to self-employment tax.';
    else seNote = 'The exclusion is for income tax only. For self-employment tax, the full ' + (mode === 'allowance' ? 'allowance' : 'rental value plus utility allowance') +
      ' (' + money.format(se.base) + ') is added to your ministerial earnings. The ' + TAX_YEAR + ' estimate uses 15.3% of 92.35% of that amount and ignores the ' +
      money.format(SS_WAGE_BASE) + ' Social Security wage base, so it overstates the tax if your total earnings are above it.';
    set('chSeNote', seNote);
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('chForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
